import QRCode from 'qrcode';
import './style.css';

const ROTATE_MS = 20_000;
const SESSION_MS = 8 * 60_000;
const APP_VERSION = '1.1.0';
const storeKey = 'kampus-yoklama-mvp-v1';
let students = [];
let course = { id:27063, code: 'PSK 301', title: 'Fizyolojik Psikoloji', room: '—', day: 'Pazartesi', time: 'OİS haftalık planı' };
const state = JSON.parse(localStorage.getItem(storeKey) || 'null') || { active: null, logs: [], screen: 'dashboard' };
state.completed ??= [];
// Eski TC-giriş oturumunu yeni hoca-kodu akışına taşımayız; yeniden doğrulama gerekir.
if (state.auth && state.auth.loginMethod !== 'instructor-id') { delete state.auth; delete state.mustChangePassword; }
let rotationTimer, tvTimer, lastServerSync=0;

const el = (s) => document.querySelector(s);
const save = () => localStorage.setItem(storeKey, JSON.stringify(state));
// Eski sürüm HTTP 200 yanıtını doğrulanmış teslimat gibi saklayabiliyordu.
// Doğrulanmamış eski özetler yeni QR oturumunda katılım göstermemelidir.
const legacyCompletedCount = state.completed.length;
state.completed = state.completed.filter(item => item.verified === true);
if (state.completed.length !== legacyCompletedCount) save();
const now = () => Date.now();
const fmt = (t) => new Intl.DateTimeFormat('tr-TR', { hour: '2-digit', minute: '2-digit', second: '2-digit' }).format(t);
const safe = (v) => String(v).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const token = () => crypto.getRandomValues(new Uint32Array(4)).join('-');
const api=async(url,options={})=>{const response=await fetch(url,{...options,headers:{...(options.headers||{}),'content-type':'application/json',...(state.auth?{authorization:`Bearer ${state.auth.token}`}:{})}});if(response.status===401&&state.auth){delete state.auth;delete state.mustChangePassword;delete state.selectedCourseId;save();setTimeout(render,0);}return response;};

function log(type, detail, severity = 'normal') {
  state.logs.unshift({ id: token(), at: now(), type, detail, severity });
  state.logs = state.logs.slice(0, 60); save();
}
function activeValid() { return state.active && now() < state.active.endsAt; }
function qrActive() { return activeValid() && state.active.qrOpen; }
function selectedMeeting(){return course.raw?.meetings?.find(x=>x.id===state.selectedMeetingId)||course.raw?.meetings?.find(x=>x.week===state.selectedWeek&&!x.isExamWeek)||course.raw?.meetings?.find(x=>x.week===state.selectedWeek)||course.raw?.meetings?.[0];}
function todaySummary(){const meeting=selectedMeeting();return state.completed.find(x=>x.courseId===course.id&&x.meetingId===meeting?.id);}
function clearTimers() { clearInterval(rotationTimer); clearTimeout(tvTimer); }
async function syncActive(){if(!state.active||now()-lastServerSync<2500)return;lastServerSync=now();const r=await api(`/api/sessions/${state.active.id}`);if(!r.ok)return;const data=await r.json(),next=data.present.map(x=>({id:x.no,name:x.name,checkedAt:x.checkedAt}));if(next.length!==state.active.present.length){state.active.present=next;save();render();}}
async function startSession() {
  const meeting=selectedMeeting(); if(!meeting)return alert('Önce OİS planından bir hafta seçin.');
  const response = await api('/api/sessions',{method:'POST',body:JSON.stringify({courseId:course.id,meetingId:meeting.id,meetingDate:meeting.date,week:meeting.week})});
  const data = await response.json(); if(!response.ok) return alert(data.error||'Oturum açılamadı');
  state.active = { id:data.id, meetingId:data.meetingId, week:data.week, apiWeek:data.apiWeek, meetingDate:data.meetingDate, meetingType:data.meetingType, absenceHours:data.absenceHours, absentField:data.absentField, presentField:data.presentField, startedAt:now(), endsAt:data.closesAt, qrToken:data.challenge, qrIssuedAt:now(), present:(data.present||[]).map(x=>({id:x.no,name:x.name,checkedAt:x.checkedAt})), previouslyDeliveredCount:data.previouslyDeliveredCount||0, qrOpen:true, openNumber:data.openNumber, maxOpens:data.maxOpens||5, opensRemaining:data.opensRemaining };
  log('QR yoklaması açıldı', `${course.code} · hafta ${data.week} · ${data.openNumber}. oturum / ${data.maxOpens||5}`); save(); render();
}
function setActiveSession(data) {
  state.active = { id:data.id, meetingId:data.meetingId, week:data.week, apiWeek:data.apiWeek, meetingDate:data.meetingDate, meetingType:data.meetingType, absenceHours:data.absenceHours, absentField:data.absentField, presentField:data.presentField, startedAt:now(), endsAt:data.closesAt, qrToken:data.challenge, qrIssuedAt:now(), present:(data.present||[]).map(x=>({id:x.no,name:x.name,checkedAt:x.checkedAt})), previouslyDeliveredCount:data.previouslyDeliveredCount||0, qrOpen:true, openNumber:data.openNumber, maxOpens:data.maxOpens||5, opensRemaining:data.opensRemaining };
}
async function startTvPairing() {
  const meeting=selectedMeeting(); if(!meeting)return alert('Önce OİS planından bir hafta seçin.');
  const r=await api('/api/tv/pairings',{method:'POST',body:JSON.stringify({courseId:course.id,meetingId:meeting.id,meetingDate:meeting.date,week:meeting.week})});
  const data=await r.json(); if(!r.ok)return alert(data.error||'TV bağlantısı başlatılamadı.');
  showTvPairingModal(data);
}
function showTvPairingModal(pairing) {
  const modal=document.createElement('div'); modal.style.cssText='position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.62);display:grid;place-items:center;padding:24px';
  modal.innerHTML=`<section role="dialog" aria-modal="true" class="card" style="width:min(580px,100%);padding:36px;text-align:center"><p class="eyebrow">TV BAĞLANTISI</p><h2>Bu kodu TV ekranında girin.</h2><div id="tv-pair-code" style="font-size:56px;letter-spacing:.16em;font-weight:800;margin:24px 0">${safe(pairing.code)}</div><p id="tv-pair-status" style="color:var(--muted);line-height:1.55">TV’de aynı siteyi açın, “TV ile giriş” seçeneğine basın ve bu kodu girin.</p><button class="primary" id="approve-tv" disabled style="display:none;margin:18px auto">Yoklamayı TV’de başlat</button><button class="ghost" id="cancel-tv-pair" style="margin-top:12px">İptal</button></section>`;
  document.body.append(modal); let closed=false;
  const close=()=>{closed=true;modal.remove();}; modal.querySelector('#cancel-tv-pair').onclick=close;
  const poll=async()=>{if(closed)return;const response=await api(`/api/tv/pairings/${pairing.id}`);const data=await response.json().catch(()=>({}));if(!response.ok){modal.querySelector('#tv-pair-status').textContent=data.error||'Bağlantı kontrol edilemedi.';return;}const status=modal.querySelector('#tv-pair-status');if(data.status==='WAITING_FOR_APPROVAL'){status.textContent='TV bağlandı. Yoklamayı yalnızca siz onayladıktan sonra TV’de QR kod görünecek.';const approve=modal.querySelector('#approve-tv');approve.style.display='block';approve.disabled=false;approve.onclick=async()=>{approve.disabled=true;const approved=await api(`/api/tv/pairings/${pairing.id}/approve`,{method:'POST'}),body=await approved.json();if(!approved.ok){status.textContent=body.error||'Yoklama başlatılamadı.';approve.disabled=false;return;}setActiveSession(body.session);log('TV ile QR yoklaması açıldı',`${course.code} · hafta ${body.session.week}`);save();close();render();};}
    else if(data.status==='EXPIRED'||data.status==='SUPERSEDED'){status.textContent='Bu TV kodunun süresi doldu. Bilgisayardan yeni kod üretin.';return;}
    setTimeout(poll,1200);
  }; poll();
}
async function closeQr() {
  if (!state.active) return;
  const r=await api(`/api/sessions/${state.active.id}/qr-close`,{method:'POST'}),data=await r.json();if(!r.ok)return alert(data.error||'QR kapatılamadı');
  state.active.qrOpen=false;state.active.qrToken=null;state.active.opensRemaining=data.opensRemaining;log('QR yoklaması kapatıldı', `${state.active.present.length} öğrenci korundu`);save();render();
}
async function endClass() {
  if (!state.active) return;
  const r=await api(`/api/sessions/${state.active.id}/end`,{method:'POST',body:JSON.stringify({week:state.active.week})}),data=await r.json();if(!r.ok){if(!data.oisDebug){alert(data.error||'Gönderim başlatılamadı.');return;}state.failedDelivery={courseId:course.id,date:state.active.meetingDate,error:data.detail||data.error,payload:data.oisPayload,debug:data.oisDebug};save();render();return showOisFailureModal(data);}
  const summary=data.summary||{total:students.length,attended:state.active.present.length,absent:Math.max(0,students.length-state.active.present.length),sent:data.delivery?.sent?students.length:0,students:[]};const completed={courseId:course.id,meetingId:state.active.meetingId,date:state.active.meetingDate,week:state.active.week,present:summary.attended,total:summary.total,openNumber:data.openNumber,maxOpens:data.maxOpens||5,endedAt:now(),obsSent:Boolean(data.delivery?.sent),accepted:Boolean(data.delivery?.accepted),verified:Boolean(data.delivery?.verified),delivery:data.delivery};state.completed=state.completed.filter(x=>!(x.courseId===completed.courseId&&x.meetingId===completed.meetingId));state.completed.unshift(completed);delete state.lastDelivery;
  log('Ders bitirildi', data.delivery?.accepted?`${summary.total} öğrenci için OİS API kabul yanıtı alındı; doğrulama bekleniyor`:`${summary.attended} öğrenci için OİS test paketi hazır`);state.active=null;save();render();showDeliverySummaryModal(summary,data.delivery,completed);
}
async function rotate() {
  if (!activeValid()) { return; }
  if (!qrActive()) { await syncActive(); return; }
  if (now() - state.active.qrIssuedAt >= ROTATE_MS) {
    const r=await api(`/api/sessions/${state.active.id}/challenge`), data=await r.json(); if(!r.ok){state.active.qrOpen=false;save();render();return;}
    state.active.qrToken = data.challenge; state.active.qrIssuedAt = now(); log('QR yenilendi', 'Sunucu yeni kısa ömürlü erişim tanıtıcısı üretti'); save();
  }
  await syncActive(); drawLive();
}
async function chooseCourse(c){course={id:c.id,code:c.code,title:c.title,room:c.room||'—',day:'OİS haftalık planı',time:`Şube ${c.section}`,raw:c};students=[];state.selectedCourseId=c.id;const stillSelected=c.meetings?.some(x=>x.id===state.selectedMeetingId);if(!stillSelected){const first=c.meetings?.find(x=>!x.isExamWeek)||c.meetings?.[0];state.selectedWeek=first?.week;state.selectedMeetingId=first?.id;}state.screen='attendance';save();render();try{const r=await api(`/api/courses/${c.id}/ois-students`,{method:'POST'}),d=await r.json();if(!r.ok)throw new Error(d.error);students=d.students.map(s=>({id:s.no,name:s.name,verified:true,department:'OİS',term:c.term}));render();}catch(error){log('OİS öğrenci listesi alınamadı',error.message,'warning');render();}}
async function showStudentStatus(){const meeting=selectedMeeting(),activeForMeeting=activeValid()&&state.active?.meetingId===meeting?.id;let delivered=!activeForMeeting?todaySummary():null;let present=new Set((activeForMeeting?state.active.present:[]||[]).map(student=>student.id));if(!activeForMeeting&&meeting){try{const r=await api(`/api/courses/${course.id}/attendance-history?meetingId=${encodeURIComponent(meeting.id)}`),data=await r.json();if(r.ok&&data.delivered){present=new Set((data.present||[]).map(student=>student.no));delivered={present:present.size,total:students.length,obsSent:true};}}catch{}}const modal=document.createElement('div');modal.style.cssText='position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.62);display:grid;place-items:center;padding:24px';const statusLabel=delivered?.obsSent?'OİS API kabul etti':'Yoklama durumu';modal.innerHTML=`<section role="dialog" aria-modal="true" class="card" style="width:min(920px,100%);max-height:88vh;overflow:auto;padding:32px"><div class="section-head"><div><p class="eyebrow">OİS ÖĞRENCİ LİSTESİ</p><h2>${safe(course.title)}</h2><p style="color:var(--muted);margin:7px 0 0">${students.length} kayıtlı öğrenci · ${present.size} yoklama alındı · ${safe(statusLabel)}</p></div><button class="ghost" id="close-student-status">Kapat</button></div><div style="overflow:auto;margin-top:18px"><table style="width:100%;border-collapse:collapse;text-align:left"><thead><tr><th style="padding:12px;border-bottom:1px solid #ddd">Öğrenci no</th><th style="padding:12px;border-bottom:1px solid #ddd">Ad soyad</th><th style="padding:12px;border-bottom:1px solid #ddd">Yoklama durumu</th></tr></thead><tbody>${students.map(student=>{const checked=present.has(student.id);return `<tr><td style="padding:13px;border-bottom:1px solid #eee">${safe(student.id)}</td><td style="padding:13px;border-bottom:1px solid #eee">${safe(student.name)}</td><td style="padding:13px;border-bottom:1px solid #eee;color:${checked?'#16803c':'#777'};font-weight:700">${checked?'✓ Yoklama alındı':'○ Bekliyor'}</td></tr>`}).join('')||'<tr><td colspan="3" style="padding:18px">Öğrenci listesi OİS’ten yükleniyor veya bulunamadı.</td></tr>'}</tbody></table></div></section>`;document.body.append(modal);modal.querySelector('#close-student-status').onclick=()=>modal.remove();}
async function readOisProgram(){const button=el('#read-ois-program');if(button){button.disabled=true;button.textContent='OİS programı okunuyor…';}try{const r=await api(`/api/courses/${course.id}/ois-program`),d=await r.json();state.oisProgramProbe={courseId:course.id,data:r.ok?d:{error:d.error,debug:d.oisDebug||null}};save();render();}catch(error){state.oisProgramProbe={courseId:course.id,data:{error:error.message}};save();render();}}
async function loadInstructorProfile(){const season=state.oisSeason||'2025-2026',semester=Number(state.oisSemester||1);try{const r=await api(`/api/instructors/me/profile?season=${encodeURIComponent(season)}&semester=${semester}`),d=await r.json();if(r.ok&&d.instructor?.name)state.auth.instructor={...state.auth.instructor,...d.instructor};}catch{}}
function loginScreen(){
  el('#app').innerHTML=`<main><section class="card" style="max-width:620px;margin:10vh auto;padding:48px"><p class="eyebrow">KAMPÜS YOKLAMA · v${APP_VERSION}</p><h1>Hoş geldiniz.</h1><p style="margin:13px 0 27px;color:var(--muted);line-height:1.5;font-size:14px">Öğretmen bilgisayarından giriş yapın veya sınıf televizyonunu kısa ekran koduyla bağlayın.</p><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:18px"><section style="border:1px solid var(--line);border-radius:14px;padding:22px"><p class="eyebrow">SİSTEM GİRİŞİ</p><label>Hoca kodu / yönetici kullanıcı adı<input id="instructor-id" autocomplete="username" placeholder="Hoca kodunuz veya yönetici adınız"></label><label>Şifre<input id="password" type="password" autocomplete="current-password" placeholder="Şifreniz"></label><button class="primary" id="login" style="width:100%;margin-top:14px">Sisteme giriş yap</button><div id="login-result"></div></section><section style="border:1px solid var(--line);border-radius:14px;padding:22px"><p class="eyebrow">SINIF EKRANI</p><h2 style="font-size:24px">TV ile giriş</h2><p style="color:var(--muted);line-height:1.55;font-size:14px">Öğretmenin bilgisayarında üretilen altı haneli ekran kodunu girin. Hoca şifresi TV’de asla yazılmaz.</p><button class="ghost" id="tv-mode" style="margin-top:20px;width:100%">TV kodunu gir</button></section></div></section></main>`;
  el('#login').onclick=async()=>{const username=el('#instructor-id').value.trim(),password=el('#password').value,out=el('#login-result');const r=await fetch('/api/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({instructorId:username,password})}),d=await r.json();if(r.ok){state.auth={token:d.token,instructor:d.instructor,loginMethod:'instructor-id'};state.courses=d.courses;state.mustChangePassword=Boolean(d.passwordChangeRequired);delete state.selectedCourseId;if(!state.mustChangePassword)await loadInstructorProfile();state.screen=state.mustChangePassword?'password-setup':'dashboard';save();return render();}const adminResponse=await fetch('/api/admin/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({username,password})}),admin=await adminResponse.json();if(!adminResponse.ok)return result(out,'Kullanıcı adı veya şifre hatalı.',false);localStorage.setItem('kampus-yoklama-admin-v1',JSON.stringify({token:admin.token,admin:admin.admin,mustChangePassword:Boolean(admin.passwordChangeRequired)}));location.assign('/admin.html');};
  el('#tv-mode').onclick=tvPairingScreen;
}
function tvPairingScreen(){
  clearTimers();
  el('#app').innerHTML=`<main><section class="card" style="max-width:520px;margin:14vh auto;padding:48px"><p class="eyebrow">SINIF EKRANI · TV MODU</p><h1>TV’yi bağlayın.</h1><p style="color:var(--muted);line-height:1.6;margin:12px 0 24px">Öğretmenin bilgisayarındaki “TV’ye bağla” düğmesinden üretilen altı haneli kodu girin. Öğretmen onayı olmadan ders veya QR görünmez.</p><label>Altı haneli ekran kodu<input id="tv-code" inputmode="numeric" maxlength="6" placeholder="000000" style="font-size:25px;letter-spacing:.22em;text-align:center"></label><button class="primary" id="connect-tv" style="width:100%;margin-top:16px">TV’yi bağla</button><div id="tv-result"></div><button class="ghost" id="teacher-login" style="margin-top:18px">Öğretmen girişine dön</button></section></main>`;
  el('#teacher-login').onclick=loginScreen;
  el('#connect-tv').onclick=async()=>{const out=el('#tv-result'),code=el('#tv-code').value.replace(/\D/g,'');if(code.length!==6)return result(out,'Altı haneli kodu girin.',false);const r=await fetch('/api/tv/connect',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({code})}),d=await r.json();if(!r.ok)return result(out,d.error||'TV bağlanamadı.',false);state.tv={displayToken:d.displayToken};save();render();};
}
async function tvDisplayScreen(){
  const response=await fetch('/api/tv/status',{headers:{'x-tv-display-token':state.tv.displayToken}});
  const data=await response.json().catch(()=>({}));
  if(!response.ok||data.status==='ENDED'||data.status==='EXPIRED'||data.status==='SUPERSEDED'){delete state.tv;save();return tvPairingScreen();}
  if(data.status==='WAITING_FOR_APPROVAL'){
    el('#app').innerHTML=`<main><section class="card" style="max-width:620px;margin:18vh auto;padding:58px;text-align:center"><p class="eyebrow">TV BAĞLANDI</p><h1>Öğretmen onayı bekleniyor.</h1><p style="color:var(--muted);margin-top:15px">Bilgisayardaki öğretmen “Yoklamayı TV’de başlat” onayını verdiğinde QR kod burada görünecek.</p></section></main>`;
  } else if(data.status==='ACTIVE') {
    const qrUrl=data.qrOpen?`${location.origin}/student.html?session=${encodeURIComponent(data.sessionId)}&challenge=${encodeURIComponent(data.challenge)}`:null;
    el('#app').innerHTML=`<main><section class="card" style="max-width:940px;margin:7vh auto;padding:42px;text-align:center"><p class="eyebrow">CANLI YOKLAMA · HAFTA ${safe(data.week)} · ${safe(data.meetingDate)}</p><h1 style="margin:6px 0">${safe(data.course.title)}</h1><p style="color:var(--muted)">${safe(data.course.code)} · Şube ${safe(data.course.section)}</p>${data.qrOpen?`<canvas id="tv-qr" style="margin:26px auto 18px"></canvas><h2>${safe(data.presentCount)} / ${safe(data.total)} öğrenci yoklama verdi</h2><p style="color:var(--muted)">QR kod otomatik yenilenir.</p>`:`<h2 style="margin-top:40px">QR okutma geçici olarak kapalı.</h2><p style="color:var(--muted)">Öğretmenin bilgisayardan yeniden açmasını bekleyin.</p>`}</section></main>`;
    if(qrUrl) await QRCode.toCanvas(el('#tv-qr'),qrUrl,{width:330,margin:1,color:{dark:'#10281f',light:'#f7fcf4'}});
  } else { delete state.tv;save();return tvPairingScreen(); }
  tvTimer=setTimeout(render,2000);
}
function passwordSetupScreen(){el('#app').innerHTML=`<main><section class="card" style="max-width:600px;margin:12vh auto;padding:54px 69px"><p class="eyebrow">HESAP GÜVENLİĞİ</p><h1>Yeni şifre belirleyin.</h1><p style="margin:13px 0 27px;color:var(--muted);line-height:1.6">Dört haneli ilk şifreniz güvenli değildir. Yoklama sistemini açmadan önce yalnızca sizin bileceğiniz yeni bir şifre oluşturun.</p><label>Yeni şifre<input id="new-password" type="password" autocomplete="new-password" placeholder="En az 10 karakter"></label><label>Yeni şifre tekrar<input id="new-password-repeat" type="password" autocomplete="new-password" placeholder="Şifrenizi yeniden girin"></label><small>En az 10 karakter, en az bir harf ve bir rakam kullanın.</small><button class="primary" id="set-password" style="width:100%;margin-top:18px">Şifreyi kaydet ve sisteme devam et</button><div id="password-result"></div></section></main>`;el('#set-password').onclick=async()=>{const value=el('#new-password').value,repeat=el('#new-password-repeat').value;if(value!==repeat)return result(el('#password-result'),'Şifreler aynı değil.',false);const r=await api('/api/auth/password',{method:'POST',body:JSON.stringify({newPassword:value})}),d=await r.json();if(!r.ok)return result(el('#password-result'),d.error,false);state.auth.instructor=d.instructor;delete state.mustChangePassword;await loadInstructorProfile();state.screen='dashboard';save();render();};}
async function logout(){clearTimers();if(state.active){try{await api(`/api/sessions/${state.active.id}/end`,{method:'POST',body:JSON.stringify({week:1})})}catch{}state.active=null;}delete state.auth;state.screen='dashboard';save();render();}
function nav() {
  return `<aside><div class="brand"><span>◈</span><div>KAMPÜS<small>YOKLAMA</small></div></div>
  <nav>${[['dashboard','Genel bakış','▦'],...(state.selectedCourseId?[['attendance','Yoklama ekranı','◷']]:[]),['students','Öğrenciler','♙'],['settings','Ayarlar','⚙'],['audit','Güvenlik kaydı','◉']].map(([id,name,i])=>`<button class="nav ${state.screen===id?'active':''}" data-nav="${id}"><i>${i}</i>${name}</button>`).join('')}</nav>
  <div class="profile"><b>${safe(state.auth.instructor.name)}</b><small>Öğretim elemanı · güvenli oturum</small><button class="ghost" id="logout" style="padding:3px 0;margin-top:5px;font-size:10px">Hesaptan çıkış</button></div></aside>`;
}
function layout(content) { const title={dashboard:'Derslerim',attendance:'Yoklama Merkezi',students:'Öğrenci kayıtları',settings:'Ayarlar',audit:'Denetim günlüğü'}[state.screen]||'Kampüs Yoklama';const period=course.raw?.term||'OİS kaydı';el('#app').innerHTML = `${nav()}<main><header><div><p class="eyebrow">${safe(period)} · v${APP_VERSION}</p><h1>${title}</h1></div><div class="status"><span></span>Güvenli bağlantı</div></header>${content}</main>`; if(state.screen==='dashboard'){el('#ois-query-tool')?.remove();el('#ois-course-result')?.parentElement?.querySelector('details')?.remove();} if(state.screen==='attendance')document.querySelector('#read-ois-program')?.closest('section')?.remove(); bindNav();el('#logout').onclick=logout; }
