async function loadOisPreview(){if(!state.active||!el('#ois-preview'))return;const panel=el('#ois-preview');try{const r=await api(`/api/sessions/${state.active.id}/ois-preview`),d=await r.json();if(!r.ok)throw new Error(d.error);const details=[['Hedef ortam',d.deliveryTarget?.label||'OİS'],['OİS adresi',d.deliveryTarget?.endpoint||'—'],['Ders adı',d.course.title],['Ders kodu',d.course.code],['Ders ID',d.course.id],['Öğretim elemanı',`${d.instructor.name} · ${d.instructor.id}`],['Sezon',d.course.academicYear],['Dönem',d.course.semester],['Şube (section)',d.course.section],['Ekrandaki hafta',d.week],['Gönderilen API haftası',d.apiWeek],['Tarih',d.date],['Gelmemiş öğrenci alanı',`${d.absentField} · ${d.absenceHours}`],['Gelen öğrenci alanı',`${d.presentField} · 0`]].map(([label,value])=>`<div><small>${safe(label)}</small><b style="word-break:break-word">${safe(value)}</b></div>`).join('');const students=d.payload.ogrenciler_saat.map(row=>`<li><b>${safe(row.ogrenci_no)}</b> → ${safe(row.saat??row.usaat??row.Usaat)} saat</li>`).join('');const failure=state.failedDelivery?.courseId===course.id&&state.failedDelivery?.date===d.date?`<div class="result no" style="display:block;margin-top:16px">Son OİS yanıtı: ${safe(state.failedDelivery.error)}</div><details style="margin-top:14px"><summary style="cursor:pointer;font-weight:700">Şifresiz teknik gönderim çıktısı</summary><pre style="white-space:pre-wrap;overflow:auto;background:#111;color:#f5f5f5;padding:15px;border-radius:10px;margin-top:10px;font-size:12px">${safe(JSON.stringify(state.failedDelivery.debug||{parameters:{ders:state.failedDelivery.payload?.ders,ogrenciler_saat:state.failedDelivery.payload?.ogrenciler_saat}},null,2))}</pre></details>`:'';panel.innerHTML=`<div class="section-head"><div><p class="eyebrow">OİS GÖNDERİM ÖNİZLEMESİ</p><h2>Bu değerler OİS’e gönderilecek.</h2></div><span class="pill">${safe(d.deliveryTarget?.label||'OİS')} · şifre gösterilmez</span></div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:14px;line-height:1.45">${details}</div><div class="note" style="margin-top:19px"><b>Öğrenci devamsızlık değerleri</b><ul style="margin:8px 0 0;padding-left:18px">${students}</ul></div>${failure}`;}catch(error){panel.innerHTML=`<p class="eyebrow">OİS GÖNDERİM ÖNİZLEMESİ</p><h2>Önizleme alınamadı.</h2><p>${safe(error.message)}</p>`}}
function livePanel() { const s=state.active; return `<section class="live"><div class="qr-card"><p class="eyebrow">CANLI YOKLAMA</p><canvas id="qr"></canvas><div class="qr-footer"><span class="pulse"></span><span id="qr-age">QR hazırlanıyor…</span></div></div><div class="live-info"><p class="eyebrow">${course.code} · ${course.room}</p><h2>Öğrenciler QR’ı telefonlarından okutur.</h2><p>QR yalnızca aktif oturum, doğrulanmış öğrenci hesabı ve zaman penceresi için geçerlidir.</p><div class="timer"><span>Kalan oturum süresi</span><b id="countdown">--:--</b></div><div class="security-list"><span>✓ Tek öğrenci / tek kayıt</span><span>✓ Eski QR otomatik reddedilir</span><span>✓ Cihaz ve IP olay günlüğü</span></div></div><div class="checkin"><p class="eyebrow">DEMO ÖĞRENCİ DOĞRULAMA</p><label>Öğrenci numarası<input id="student-id" placeholder="2024001" inputmode="numeric"></label><label>QR erişim anahtarı<input id="scan-token" placeholder="QR okutulunca otomatik gelir"></label><button class="primary" id="checkin">Kimliğimi doğrula ve yoklama ver</button><small>Üretimde: üniversite SSO + cihazda WebAuthn / biyometrik onay.</small><div id="result"></div></div></section>`; }
async function drawLive() {
  if (!qrActive() || !el('#qr')) return;
  const s=state.active, remaining=Math.max(0, ROTATE_MS-(now()-s.qrIssuedAt));
  const payload = `${location.origin}/student.html?session=${encodeURIComponent(s.id)}&challenge=${encodeURIComponent(s.qrToken)}`;
  await QRCode.toCanvas(el('#qr'), payload, { width: 210, margin: 1, color: { dark:'#10281f', light:'#f7fcf4' }});
  const age=el('#qr-age'), count=el('#countdown');
  if(age) age.textContent=`Yeni QR ${Math.ceil(remaining/1000)} sn sonra üretilecek`;
  if(count) { const left=Math.max(0,s.endsAt-now()), m=String(Math.floor(left/60000)).padStart(2,'0'), sec=String(Math.floor(left/1000)%60).padStart(2,'0'); count.textContent=`${m}:${sec}`; }
  const tokenInput=el('#scan-token'); if(tokenInput && !tokenInput.value) tokenInput.placeholder = `Demo anahtarı: ${s.qrToken}`;
}
async function checkIn() {
  const studentId=el('#student-id').value.trim(), submitted=el('#scan-token').value.trim(); const out=el('#result');
  if (!qrActive()) return result(out, 'QR yoklaması kapalı veya süresi dolmuş.', false);
  const student=students.find(x=>x.id===studentId);
  if (!student || !student.verified) { log('Reddedilen doğrulama', `Bilinmeyen/doğrulanmamış öğrenci: ${studentId||'boş'}`, 'warn'); return result(out,'Öğrenci hesabı doğrulanamadı.',false); }
  if (submitted !== state.active.qrToken) { log('Reddedilen QR', `${studentId} için geçersiz ya da eski QR`, 'warn'); return result(out,'Bu QR geçersiz veya süresi dolmuş.',false); }
  // QR içindeki challenge doğrudan yoklama kaydı için kullanılmaz. Sunucu önce
  // kısa ömürlü bir doğrulama bileti üretir; bu bilet olmadan kayıt reddedilir.
  const validationResponse=await fetch(`/api/checkin/validate?session=${encodeURIComponent(state.active.id)}&challenge=${encodeURIComponent(submitted)}`), validation=await validationResponse.json();
  if(!validationResponse.ok)return result(out,validation.error||'QR doğrulanamadı.',false);
  const response=await fetch('/api/attendance/claim',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({sessionId:state.active.id,ticket:validation.ticket,studentNo:studentId})}), data=await response.json();
  if(!response.ok)return result(out,data.error||'Yoklama kaydedilemedi.',false);
  const attendance={...student, checkedAt:now(), device:'Onaylı mobil cihaz', ip:'Kayıtlı ağ bölgesi'}; state.active.present.push(attendance); log('Yoklama kaydedildi', `${student.id} · ${student.name}`); save(); result(out,`${student.name}, yoklaman kaydedildi.`,true); render();
}
function result(out, text, yes) { out.className=`result ${yes?'yes':'no'}`; out.textContent=text; }
function showOisFailureModal(data){const debug=data.oisDebug||{environmentLabel:'OİS',endpoint:'OİS yanıtı alınamadı',httpMethod:'GET',parameters:{method:'yoklama',ders:data.oisPayload?.ders,ogrenciler_saat:data.oisPayload?.ogrenciler_saat},response:data.detail||data.error};const report={environment:debug.environmentLabel||debug.environment,endpoint:debug.endpoint,httpMethod:debug.httpMethod,transport:debug.transport||null,parameters:debug.parameters,httpStatus:debug.httpStatus,networkError:debug.networkError||null,response:debug.response};const modal=document.createElement('div');modal.style.cssText='position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.62);display:grid;place-items:center;padding:24px';modal.innerHTML=`<section role="dialog" aria-modal="true" class="card" style="width:min(900px,100%);max-height:88vh;overflow:auto;padding:32px"><div class="section-head"><div><p class="eyebrow">OİS GÖNDERİM RAPORU</p><h2>OİS isteği reddetti.</h2></div><button class="ghost" id="close-ois-report">Kapat</button></div><div class="result no" style="display:block;margin:12px 0 20px">${safe(data.detail||data.error||'Bilinmeyen hata')}</div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin-bottom:18px"><div><small>Hedef ortam</small><b>${safe(debug.environmentLabel||debug.environment||'OİS')}</b></div><div><small>Gönderim yöntemi</small><b>${safe(debug.httpMethod||'GET')}</b></div><div><small>Endpoint</small><b style="word-break:break-all">${safe(debug.endpoint||'—')}</b></div><div><small>HTTP durumu</small><b>${safe(debug.httpStatus||'—')}</b></div></div><p style="color:var(--muted);font-size:13px;line-height:1.5">Aşağıdaki değerler sunucudan OİS’e ayrı parametreler halinde gönderildi. API kullanıcı adı ve şifresi güvenlik nedeniyle bu raporda yer almaz.</p><pre style="white-space:pre-wrap;overflow:auto;background:#111;color:#f5f5f5;padding:16px;border-radius:10px;font-size:12px;line-height:1.55">${safe(JSON.stringify(report,null,2))}</pre><button class="primary" id="close-ois-report-bottom" style="float:right">Raporu kapat</button></section>`;document.body.append(modal);const close=()=>modal.remove();modal.querySelector('#close-ois-report').onclick=close;modal.querySelector('#close-ois-report-bottom').onclick=close;}
function showDeliverySummaryModal(summary, delivery, completed) {
  const modal=document.createElement('div');
  modal.style.cssText='position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.62);display:grid;place-items:center;padding:24px';
  const rows=(summary.students||[]).map(student=>`<tr><td style="padding:13px;border-bottom:1px solid #eee">${safe(student.no)}</td><td style="padding:13px;border-bottom:1px solid #eee">${safe(student.name)}</td><td style="padding:13px;border-bottom:1px solid #eee;color:${student.attended?'#16803c':'#777'};font-weight:700">${student.attended?'✓ Yoklama alındı':'○ Gelmedi'}</td><td style="padding:13px;border-bottom:1px solid #eee;color:#9a6700;font-weight:700">⌛ OİS yanıtı alındı; kayıt doğrulanmadı</td></tr>`).join('');
  const diagnostics=delivery?.diagnostics||null;
  const diagnosticReport=diagnostics?{httpStatus:diagnostics.httpStatus,transport:diagnostics.transport,endpoint:diagnostics.endpoint,request:diagnostics.request,rawResponse:diagnostics.rawResponse}:{deliveryMode:delivery?.mode||null,serverResponse:delivery?.response||delivery?.message||'Sunucu ayrıntısı alınamadı.'};
  const diagnosticPanel=`<details open style="margin:22px 0 0"><summary style="cursor:pointer;font-weight:700">OİS sunucusunun gerçek yanıtı ve gönderim ayrıntısı</summary><p style="color:var(--muted);font-size:13px;line-height:1.5;margin:10px 0">Bu alan OİS’in döndürdüğü ham yanıtı ve şifresiz istek verisini gösterir. API kullanıcı adı ve şifresi asla gösterilmez.</p><pre style="white-space:pre-wrap;overflow:auto;background:#111;color:#f5f5f5;padding:16px;border-radius:10px;font-size:12px;line-height:1.55">${safe(JSON.stringify(diagnosticReport,null,2))}</pre></details>`;
  modal.innerHTML=`<section role="dialog" aria-modal="true" class="card" style="width:min(1040px,100%);max-height:88vh;overflow:auto;padding:32px"><div class="section-head"><div><p class="eyebrow">OİS GÖNDERİM ÖZETİ</p><h2>OİS yanıt verdi; kayıt doğrulanmadı.</h2><p style="color:var(--muted);margin-top:8px">${safe(delivery?.environmentLabel||'OİS')} · ${safe(completed.week)}. hafta · ${safe(completed.date)}</p></div><button class="ghost" id="close-delivery-summary">Kapat</button></div><div class="note" style="margin-top:18px"><b>Bu sonuç OİS kaydının oluştuğunu kanıtlamaz.</b><p style="margin:8px 0 0;line-height:1.5">${safe(delivery?.verificationNote||'OİS raporunda görünene kadar bu istek doğrulanmamış kabul edilir.')}</p></div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:11px;margin:22px 0"><div class="note"><small>OİS’te doğrulanan kayıt</small><strong style="font-size:30px;display:block;margin-top:8px">${summary.sent}</strong></div><div class="note"><small>Yoklama alınan</small><strong style="font-size:30px;display:block;margin-top:8px;color:#16803c">${summary.attended}</strong></div><div class="note"><small>Gelmedi</small><strong style="font-size:30px;display:block;margin-top:8px">${summary.absent}</strong></div><div class="note"><small>Oturum hakkı</small><strong style="font-size:30px;display:block;margin-top:8px">${completed.openNumber}/${completed.maxOpens}</strong></div></div><div style="overflow:auto"><table style="width:100%;border-collapse:collapse;text-align:left"><thead><tr><th style="padding:12px;border-bottom:1px solid #ddd">Öğrenci no</th><th style="padding:12px;border-bottom:1px solid #ddd">Ad soyad</th><th style="padding:12px;border-bottom:1px solid #ddd">Yoklama durumu</th><th style="padding:12px;border-bottom:1px solid #ddd">Gönderim durumu</th></tr></thead><tbody>${rows||'<tr><td colspan="4" style="padding:18px">Öğrenci listesi bulunamadı.</td></tr>'}</tbody></table></div>${diagnosticPanel}<button class="primary" id="close-delivery-summary-bottom" style="float:right;margin-top:22px">Tamam</button></section>`;
  document.body.append(modal); const close=()=>modal.remove(); modal.querySelector('#close-delivery-summary').onclick=close;modal.querySelector('#close-delivery-summary-bottom').onclick=close;
}
function studentCheckin(challenge) {
  const valid = activeValid() && state.active.qrToken === challenge;
  el('#app').innerHTML = `<main><section class="card" style="max-width:520px;margin:12vh auto;padding:34px"><p class="eyebrow">GÜVENLİ YOKLAMA</p><h1>${valid ? course.title : 'QR geçersiz'}</h1><p style="color:var(--muted);line-height:1.7;font-size:13px;margin:13px 0 24px">${valid ? 'Ders oturumu açık. Kurum hesabınla kimliğini doğrulayıp yoklamanı ver.' : 'Bu QR artık geçerli değil. Sınıftaki güncel QR’ı yeniden okutun.'}</p>${valid ? `<label style="display:block;font-size:12px;font-weight:700">Öğrenci numarası<input id="mobile-student-id" placeholder="Örn. 2024001" inputmode="numeric" style="display:block;width:100%;margin:7px 0 13px;padding:12px;border:1px solid var(--line);border-radius:7px"></label><div style="font-size:11px;background:#eaf5e7;color:var(--green);padding:11px;border-radius:7px;margin-bottom:14px">✓ Bu cihazda öğrenci hesabı ve biyometrik onay doğrulanacak.</div><button class="primary" style="width:100%" id="mobile-checkin">Kimliğimi doğrula</button><div id="mobile-result"></div>` : `<a class="primary" href="${location.pathname}">Ana sayfaya dön</a>`}<small style="line-height:1.6;margin-top:17px">Demo ortamı: gerçek kurulumda bu ekran üniversite SSO ve WebAuthn/passkey doğrulamasına devredilir.</small></section></main>`;
  el('#mobile-checkin')?.addEventListener('click', () => {
    const studentId = el('#mobile-student-id').value.trim(), student = students.find(x => x.id === studentId), out = el('#mobile-result');
    if (!student || !student.verified) { log('Reddedilen doğrulama', `Bilinmeyen öğrenci: ${studentId||'boş'}`, 'warn'); return result(out, 'Kurum hesabı doğrulanamadı.', false); }
    if (!activeValid() || state.active.qrToken !== challenge) { log('Reddedilen QR', `${student.id} için süresi dolmuş QR`, 'warn'); return result(out, 'QR süresi doldu. Güncel QR’ı okutun.', false); }
    if (state.active.present.some(p => p.id === student.id)) { log('Tekrar yoklama engellendi', `${student.id} · ${student.name}`, 'warn'); return result(out, 'Yoklamanız daha önce kaydedilmiş.', false); }
    state.active.present.push({...student, checkedAt: now(), device:'Onaylı mobil cihaz', ip:'Kayıtlı ağ bölgesi'}); log('Yoklama kaydedildi', `${student.id} · ${student.name}`); save(); result(out, `Başarılı. ${student.name}, yoklamanız kaydedildi.`, true);
  });
}
function sessions() { layout(`<section class="card table"><div class="section-head"><div><p class="eyebrow">TANIMLAR</p><h2>Ders ve haftalık oturumlar</h2></div><button class="primary" id="add">+ Oturum tanımla</button></div><div class="course-line"><span class="course-icon">⌘</span><div><b>${course.title}</b><small>${course.code} · ${course.room} · ${students.length} kayıtlı öğrenci</small></div><span class="pill green">Yayınlandı</span></div>${['07 Ağustos 2026 · 10:00–11:40','14 Ağustos 2026 · 10:00–11:40','21 Ağustos 2026 · 10:00–11:40'].map((x,i)=>`<div class="row"><div class="date"><b>${String(7+i*7).padStart(2,'0')}</b><span>Ağu</span></div><div><b>${x}</b><small>Hafta ${i+1} · ${course.room}</small></div><span class="pill">${i===0&&activeValid()?'Canlı':'Planlandı'}</span></div>`).join('')}</section>`); el('#add').onclick=()=>alert('MVP: üretimde bu form bölüm, dönem, ders ve tekrar kuralı seçerek oturum oluşturur.'); }
